int setup_efi(struct boot_params *params, unsigned long params_load_addr,
              unsigned int efi_map_offset, unsigned int efi_map_sz,
              unsigned int efi_setup_data_offset)
{
    if (!efi_map_sz)
        return 0;

    if (!(efi_memmap_enable & 1))
        return 0;

    memcpy((void *)params_load_addr + efi_map_offset,
           (void *)&boot_params->efi_info, sizeof(boot_params->efi_info));

    params->efi_info = boot_params->efi_info;
    params->efi_map = (void *)((unsigned long)params_load_addr + efi_map_offset);
    params->efi_map_size = efi_map_sz;
    params->efi_setup_data = (void *)((unsigned long)params_load_addr +
                                      efi_setup_data_offset);

    return 0;
}

int efi_init(struct boot_params *params, unsigned long params_load_addr,
             unsigned int efi_map_offset, unsigned int efi_map_sz,
             unsigned int efi_setup_data_offset)
{
    if (!efi_map_sz)
        return 0;

    if (!efi_enabled(EFI_BOOTSERVICES) || !efi_enabled(EFI_RUNTIME_SERVICES))
        return 0;

    memcpy((void *)params_load_addr + efi_map_offset,
           (void *)params->efi_map, efi_map_sz);

    params->efi_map = efi_map_offset;
    params->efi_map_size = efi_map_sz;
    params->efi_setup_data = efi_setup_data_offset;

    return 0;
}

int init_efi_state(struct boot_params *params, unsigned long params_load_addr,
                   unsigned int efi_map_offset, unsigned int efi_map_sz,
                   unsigned int efi_setup_data_offset) {
    if (!efi_map_sz) {
        return 0;
    }

    if (!is_1to1_mapping_enabled()) {
        return 0;
    }

    copy_efi_info(params, params_load_addr);
    setup_efi_memory_map(params, efi_map_offset, efi_map_sz);
    prepare_efi_setup_data(params, efi_setup_data_offset);

    return 0;
}

