int setup_efi(struct boot_params *params, unsigned long params_load_addr,
              unsigned int efi_map_offset, unsigned int efi_map_sz,
              unsigned int efi_setup_data_offset) {
    if (!efi_map_sz)
        return 0;

    if (!efi_enabled(EFI_RUNTIME_SERVICES))
        return 0;

    memcpy((void *)params_load_addr + efi_map_offset,
           (void *)params + efi_map_offset, efi_map_sz);

    params->efi_info.efi_map = (void *)params_load_addr + efi_map_offset;
    params->efi_info.efi_map_size = efi_map_sz;
    params->efi_info.efi_setup_data = (void *)params_load_addr +
                                      efi_setup_data_offset;

    return 0;
}
